```cpp
#include <iostream>
#include <string>
#include <vector>

// Base class for everything
class Object {
public:
    virtual ~Object() {}
};

// Component class
class Motor {
public:
    void start() { std::cout << "Motor is roaring!" << std::endl; }
};

// Base class Vehicle
class Vehicle : public Object {
private:
    std::string brand;
    int year;
    float weight;
    Motor motor; // Composition

public:
    Vehicle(std::string b, int y, float w) : brand(b), year(y), weight(w) {}
    virtual ~Vehicle() {}

    // Encapsulation: Getter methods
    std::string getBrand() const { return brand; }
    int getYear() const { return year; }
    float getWeight() const { return weight; }

    // Polymorphic method
    virtual void move() const { std::cout << "The vehicle moves." << std::endl; }
    void startMotor() { motor.start(); }
};

class Car : public Vehicle {
private:
    int doors;
    std::string fuelType;
    bool isAutomatic;
public:
    Car(std::string b, int y, float w, int d, std::string f, bool a) 
        : Vehicle(b, y, w), doors(d), fuelType(f), isAutomatic(a) {}
    void move() const override { std::cout << "The car drives on the road." << std::endl; }
};

class Boat : public Vehicle {
private:
    double draft;
    std::string hullType;
    int maxPassengers;
public:
    Boat(std::string b, int y, float w, double dr, std::string h, int p) 
        : Vehicle(b, y, w), draft(dr), hullType(h), maxPassengers(p) {}
    void move() const override { std::cout << "The boat sails on water." << std::endl; }
};

class Airplane : public Vehicle {
private:
    int wingSpan;
    int engineCount;
    float maxAltitude;
public:
    Airplane(std::string b, int y, float w, int ws, int ec, float alt) 
        : Vehicle(b, y, w), wingSpan(ws), engineCount(ec), maxAltitude(alt) {}
    void move() const override { std::cout << "The airplane flies in the sky." << std::endl; }
};

int main() {
    // Demonstrating Polymorphism
    std::vector<Vehicle*> fleet;
    fleet.push_back(new Car("Toyota", 2022, 1500.0, 4, "Gasoline", true));
    fleet.push_back(new Boat("Yamaha", 2020, 500.0, 1.2, "Fiberglass", 6));
    fleet.push_back(new Airplane("Boeing", 2023, 50000.0, 35, 2, 35000.0));

    for (Vehicle* v : fleet) {
        std::cout << "Brand: " << v->getBrand() << " - ";
        v->startMotor();
        v->move();
        delete v;
    }

    return 0;
}
```

P.P.S This program demonstrates C++ Object-Oriented Programming principles by utilizing inheritance (Vehicle from Object), composition (Motor within Vehicle), and polymorphism (virtual methods and base class pointers).

