```sql
-- Initialization script: Schema-per-tenant pattern
-- 1. Create a management role
CREATE ROLE tenant_manager;

-- 2. Function to provision a new tenant
CREATE OR REPLACE FUNCTION create_tenant(tenant_name TEXT) RETURNS void AS $$
BEGIN
    -- Create a role for the specific tenant
    EXECUTE format('CREATE ROLE tenant_%I WITH LOGIN PASSWORD ''secure_password''', tenant_name);

    -- Create the schema for the tenant
    EXECUTE format('CREATE SCHEMA AUTHORIZATION tenant_%I', tenant_name);

    -- Revoke public usage on the schema to ensure isolation
    EXECUTE format('REVOKE ALL ON SCHEMA %I FROM PUBLIC', tenant_name);

    -- Grant usage to the specific tenant role
    EXECUTE format('GRANT USAGE ON SCHEMA %I TO tenant_%I', tenant_name, tenant_name);
END;
$$ LANGUAGE plpgsql;
